$$\begin{array}{l}
  {{f^{\prime}{(x)}} = {\lim\limits_{h\rightarrow 0}\frac{f{({x + h})} - f{(x)}}{h} = \lim\limits_{h\rightarrow 0}\frac{{({x + h})}^{4} - x^{4}}{h}}} \\
  {\phantom{f^{\prime}{(x)}} = {\lim\limits_{h\rightarrow 0}\frac{x^{4} + 4x^{3}h + 6x^{2}h^{2} + 4xh^{3} + h^{4} - x^{4}}{h}}} \\
  {\phantom{f^{\prime}{(x)}} = {\lim\limits_{h\rightarrow 0}\frac{4x^{3}h + 6x^{2}h^{2} + 4xh^{3} + h^{4}}{h}}} \\
  {\phantom{f^{\prime}{(x)}} = {\lim\limits_{h\rightarrow 0}{({4x^{3} + 6x^{2}h + 4xh^{2} + h^{3}})} = 4x^{3}}}
  \end{array}$$

$$\begin{array}{l}
  {{f^{\prime}{(x)}} = {\lim\limits_{h\rightarrow 0}\frac{f{({x + h})} - f{(x)}}{h} = \lim\limits_{h\rightarrow 0}\frac{b^{ x + h} - b^{ x}}{h}}} \\
  {\phantom{f^{\prime}{(x)}} = {\lim\limits_{h\rightarrow 0}\frac{b^{ x}b^{ h} - b^{ x}}{h} = \lim\limits_{h\rightarrow 0}\frac{b^{ x}{({b^{ h} - 1})}}{h}}}
  \end{array}$$

$$\begin{matrix}
  {g(x) = kx^{3} + lx^{2} + mx + n} & {0 \leqslant x < 10} \\
  {h(x) = px^{3} + qx^{2} + rx + s} & {90 < x \leqslant 100}
  \end{matrix}$$
